// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance / 2);
        vm.assume(actor != address(0));

        uint256 balanceBefore = address(c).balance;
        address targetView = address(0);
        uint256 zeroBalBefore = c.getBalance(targetView);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 balanceAfter = address(c).balance;
        uint256 zeroBalAfter = c.getBalance(targetView);
        assertTrue(balanceBefore + amount == balanceAfter && zeroBalAfter == zeroBalBefore);
    }
}
